def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]
    opp_c = sum(1 for _, o in history if o == 'C')
    opp_d = n - opp_c

    if opp_c == 0:
        return 'D'

    if opp_d > opp_c and opp_d >= 0.6 * n:
        return 'D'

    c_c = c_d = d_c = d_d = 0
    for i in range(n - 1):
        m = history[i][0]
        o = history[i + 1][1]
        if m == 'C':
            if o == 'C':
                c_c += 1
            else:
                c_d += 1
        else:
            if o == 'C':
                d_c += 1
            else:
                d_d += 1

    pC_C = (c_c + 1) / (c_c + c_d + 2)
    pC_D = (d_c + 1) / (d_c + d_d + 2)
    cond = pC_C - pC_D

    streak_opp_D = 0
    if opp_last == 'D':
        for _, o in reversed(history):
            if o == 'D':
                streak_opp_D += 1
            else:
                break

    if my_last == 'D' and opp_last == 'C':
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
            if opp_c >= opp_d:
                return 'D'
        if n >= 2 and history[-2][1] == 'D':
            if opp_c >= opp_d and cond < 0.65:
                return 'D'
        if opp_c == n:
            return 'D'

    if opp_c == n and n >= 30:
        return 'D'

    if n >= 15:
        opp = [h[1] for h in history]
        start = max(0, n - 15)
        win = opp[start:]
        win_d = sum(1 for o in win if o == 'D')
        win_c = len(win) - win_d
        if win_d >= 2 and win_c >= 2 and opp_d <= 0.75 * n:
            period_ok = False
            for p in range(2, 9):
                total = n - start - p
                if total < 8:
                    continue
                matches = 0
                for i in range(start + p, n):
                    if opp[i] == opp[i - p]:
                        matches += 1
                if total >= 8 and matches * 10 >= total * 9:
                    period_ok = True
                    break
            if period_ok and cond < 0.45:
                return 'D'

    if d_c + d_d >= 2 and cond < 0.25 and opp_d <= 0.75 * n:
        return 'D'

    if opp_last == 'D':
        if opp_c > opp_d:
            if streak_opp_D >= 5:
                return 'C'
            if streak_opp_D >= 2:
                pre = n - streak_opp_D - 1
                if pre < 0 or history[pre][0] == 'C':
                    return 'D'
                return 'C'
            if opp_d <= 0.25 * n:
                return 'C'
            return 'D'
        return 'D'

    return 'C'
